175:     } else if (this.phase === 'dawn') {
176:       this.dawnTimer += dt;
177:       this.updatePlayer(dt);
178:       if (this.dawnTimer >= 4.3) this.startDay(this.day + 1);
179:     }
180: 
181:     this.updateTowers(dt);
182:     this.updateEnemies(dt);
183:     this.updateProjectiles(dt);
184:     this.updateParticles(dt);
185:     this.updateFloaters(dt);
186:     this.updateRings(dt);
187:     this.updateNearby();
188: 
189:     for (const pad of this.pads) pad.pulse += dt * 1.4;
190:   }
191: 
192:   updatePlayer(dt) {
193:     const p = this.player;
194:     let ix = 0;
195:     let iy = 0;
196:     const keys = this.keys || {};
197:     if (keys.left) ix -= 1;
198:     if (keys.right) ix += 1;
199:     if (keys.up) iy -= 1;
200:     if (keys.down) iy += 1;
201:     ix += this.moveVector.x;
202:     iy += this.moveVector.y;
203: 
204:     if (Math.abs(ix) > 0.06 || Math.abs(iy) > 0.06) {
205:       this.walkTarget = null;
206:       const len = Math.hypot(ix, iy) || 1;
207:       ix /= len;
208:       iy /= len;
209:       p.facing = ix < -0.05 ? -1 : ix > 0.05 ? 1 : p.facing;
210:       this.tryMove(ix * p.speed * dt, iy * p.speed * dt);
211:       p.walkPhase += dt * 11.5;
212:       p.moving = true;
213:     } else if (this.walkTarget) {
214:       const t = this.walkTarget;
215:       const d = dist(p.x, p.y, t.x, t.y);
216:       const stop = t.stop || 4;
217:       if (d <= stop) {
218:         this.walkTarget = null;
219:         p.moving = false;
220:         if (t.action) t.action();
221:       } else {
222:         const nx = (t.x - p.x) / d;
223:         const ny = (t.y - p.y) / d;
224:         if (nx < -0.05) p.facing = -1;
225:         else if (nx > 0.05) p.facing = 1;
226:         const beforeX = p.x;
227:         const beforeY = p.y;
228:         this.tryMove(nx * p.speed * 0.95 * dt, ny * p.speed * 0.95 * dt);
229:         if (Math.abs(beforeX - p.x) < 0.01 && Math.abs(beforeY - p.y) < 0.01) {
230:           this.walkStuck += dt;
231:           if (this.walkStuck > 0.35) {
232:             this.walkTarget = null;
233:             this.walkStuck = 0;
234:             p.moving = false;
235:           }
236:         } else {
237:           this.walkStuck = 0;
238:           p.walkPhase += dt * 10.5;
239:           p.moving = true;
240:         }
241:       }
242:     } else {
243:       p.moving = false;
244:       p.walkPhase += dt * 2.2;
245:     }
246: 
247:     this.clampPlayer();
248:     p.vx = ix;
249:     p.vy = iy;
250:     p.lanternSwing = Math.sin(this.time * 2.4) * 0.06 + (p.moving ? Math.sin(p.walkPhase) * 0.04 : 0);
251:   }
252: 
253:   tryMove(dx, dy) {
254:     const p = this.player;
255:     const nextX = clamp(p.x + dx, 22, WORLD.w - 22);
256:     if (!this.blocked(nextX, p.y)) p.x = nextX;
257:     const nextY = clamp(p.y + dy, 26, WORLD.h - 20);
258:     if (!this.blocked(p.x, nextY)) p.y = nextY;
259:   }
260: 
261:   clampPlayer() {
262:     this.player.x = clamp(this.player.x, 22, WORLD.w - 22);
263:     this.player.y = clamp(this.player.y, 26, WORLD.h - 20);
264:   }
265: 
266:   blocked(x, y) {
267:     if (
268:       x > HOUSE_BLOCK.x && x < HOUSE_BLOCK.x + HOUSE_BLOCK.w &&
269:       y > HOUSE_BLOCK.y && y < HOUSE_BLOCK.y + HOUSE_BLOCK.h
270:     ) return true;
271:     const px = (x - POND.x) / (POND.rx - 12);
272:     const py = (y - POND.y) / (POND.ry - 10);
273:     if (px * px + py * py < 1) return true;
274:     return false;
275:   }
