277:   // ---------------------------------------------------------------- phases
278: 
279:   beginNight() {
280:     if (this.phase === 'night') return;
281:     this.phase = 'night';
282:     this.phaseTime = 0;
283:     this.nightTime = 0;
284:     this.nightOver = false;
285:     this.nightClearTimer = 0;
286:     this.nightKills = 0;
287:     this.spawnQueue = buildWave(this.day);
288:     this.spawnIndex = 0;
289:     this.nightTotal = this.spawnQueue.length;
290:     this.enemies = [];
291:     this.projectiles = [];
292:     this.rings = [];
293:     this.walkTarget = null;
294:     this.player.x = clamp(this.player.x, 40, WORLD.w - 40);
295:     this.player.y = clamp(this.player.y, 44, WORLD.h - 34);
296:     this.audio.setPhase('night');
297:     this.audio.nightStart();
298:     this.emit('night-start', { night: this.day, total: this.nightTotal });
299:     this.emit('event', {
300:       kicker: `Night ${this.day} of ${TOTAL_NIGHTS}`,
301:       title: 'The hollow wakes',
302:       sub: 'Shadows are gathering at the treeline. Raise a ward.',
303:       duration: 4600,
304:     });
305:     if (!this.tutorial.night) {
306:       this.tutorial.night = true;
307:       this.emit('toast', { text: 'Click a stone pad to build a ward before the shadows arrive.', tone: '', icon: '#i-lantern' });
308:     }
309:   }
310: 
311:   updateNight(dt) {
312:     this.nightTime += dt;
313:     while (this.spawnIndex < this.spawnQueue.length && this.spawnQueue[this.spawnIndex].t <= this.nightTime) {
314:       this.spawnEnemy(this.spawnQueue[this.spawnIndex].type);
315:       this.spawnIndex++;
316:     }
317:     const alive = this.enemies.some((e) => !e.dead);
318:     if (!this.nightOver && this.spawnIndex >= this.spawnQueue.length && !alive) {
319:       this.nightOver = true;
320:       this.nightClearTimer = 0;
321:       this.emit('event', {
322:         kicker: 'The last shadow fades',
323:         title: 'Dawn is near',
324:         sub: 'The lanterns gutter. The field is quiet.',
325:         duration: 2800,
326:       });
327:       this.audio.dawn();
328:     }
329:     if (this.nightOver) {
330:       this.nightClearTimer += dt;
331:       if (this.nightClearTimer >= NIGHT_CLEAR_DELAY) this.finishNight();
332:     }
333:   }
334: 
335:   finishNight() {
336:     if (this.phase !== 'night') return;
337:     this.stats.nights = this.day;
338:     const reward = NIGHT_REWARDS[this.day] || 200;
339:     this.nightReward = reward;
340:     this.coins += reward;
341:     this.stats.coinsEarned += reward;
342:     this.enemies = [];
343:     this.projectiles = [];
344:     this.rings = [];
345:     this.phase = 'dawn';
346:     this.phaseTime = 0;
347:     this.dawnTimer = 0;
348:     this.hearts = Math.min(MAX_HEARTS, this.hearts + 3);
349:     this.water = WATER_CAPACITY;
350:     this.audio.setPhase('day');
351:     this.audio.dawn();
352:     if (this.day >= TOTAL_NIGHTS) {
353:       this.victory();
354:       return;
355:     }
356:     this.emit('dawn', { night: this.day, reward, hearts: this.hearts });
357: 
358:     // Crops grow at first light if they were watered.
359:     let grew = 0;
360:     let matured = 0;
361:     for (const plot of this.plots) {
362:       if (!plot.crop) continue;
363:       if (plot.watered) {
364:         plot.crop.growth = Math.min(this.cropDef(plot.crop).days, plot.crop.growth + 1);
365:         grew++;
366:         if (plot.crop.growth >= this.cropDef(plot.crop).days) {
367:           matured++;
368:           this.spawnHarvestSparkle(plot);
369:         }
370:       }
371:       plot.watered = false;
372:     }
373:     if (grew > 0) {
374:       this.emit('toast', {
375:         text: matured > 0 ? `${matured} crop${matured > 1 ? 's' : ''} ready to harvest.` : `${grew} crop${grew > 1 ? 's' : ''} grew overnight.`,
376:         tone: 'good', icon: '#i-sparkle',
377:       });
378:     }
379:   }
