381:   startDay(n) {
382:     this.phase = 'day';
383:     this.day = n;
384:     this.phaseTime = 0;
385:     this.enemies = [];
386:     this.spawnQueue = [];
387:     this.projectiles = [];
388:     this.rings = [];
389:     this.nightOver = false;
390:     this.water = WATER_CAPACITY;
391:     this.player.x = 700;
392:     this.player.y = 500;
393:     this.walkTarget = null;
394:     this.audio.setPhase('day');
395:     this.emit('day-start', { day: n });
396:     this.emit('event', {
397:       kicker: `Day ${n} of ${TOTAL_NIGHTS}`,
398:       title: n === 2 ? 'Morning light' : `Day ${n}`,
399:       sub: 'The field is dew-wet. Tend what you can before dusk.',
400:       duration: 3200,
401:     });
402:   }
