435:   selectTool(index) {
436:     this.selectedTool = clamp(index, 0, TOOLS.length - 1);
437:     this.audio.click();
438:     this.emit('tool', this.selectedTool);
439:     const tool = TOOLS[this.selectedTool];
440:     if (tool.kind === 'seed') {
441:       const crop = CROPS[tool.id];
442:       this.emit('toast', {
443:         text: `${crop.name} seed · ${crop.cost} coins · sells for ${crop.sell} after ${crop.days} day${crop.days > 1 ? 's' : ''}.`,
444:         tone: '', icon: crop.icon, short: true,
445:       });
