448: 
449:   actOnPlot(plot) {
450:     if (!plot) return;
451:     const tool = TOOLS[this.selectedTool];
452:     if (plot.crop) {
453:       const def = CROPS[plot.crop.type];
454:       if (plot.crop.growth >= def.days) {
455:         this.harvest(plot);
456:       } else if (!plot.watered) {
457:         this.waterPlot(plot);
458:       } else {
459:         const left = def.days - plot.crop.growth;
460:         this.emit('toast', {
461:           text: `${def.name} is watered — ${left} more day${left > 1 ? 's' : ''} until harvest.`,
462:           tone: '', icon: def.icon, short: true,
463:         });
464:         this.audio.error();
465:       }
466:       return;
467:     }
468:     if (!plot.tilled) {
469:       this.tillPlot(plot);
470:       if (tool.kind !== 'seed') return;
471:     }
472:     if (tool.kind === 'seed') {
473:       this.plantSeed(plot, tool.id);
474:     } else if (tool.id === 'water') {
475:       this.waterPlot(plot);
476:     } else {
477:       this.emit('toast', { text: 'Choose a seed from the hotbar to plant here.', tone: '', icon: '#i-sparkle', short: true });
478:     }
479:   }
480: 
481:   tillPlot(plot) {
482:     if (plot.tilled) return;
483:     plot.tilled = true;
484:     plot.watered = false;
485:     this.audio.till();
486:     this.burst(plot.x, plot.y + 8, 12, ['#6d4a30', '#8b6240', '#4e3524'], 1.1, 34, 0.55);
487:     this.emit('tool-done', 'till');
488:     if (!this.tutorial.till) {
489:       this.tutorial.till = true;
490:       this.emit('toast', { text: 'Soil turned. Choose a seed, then plant and water it.', tone: 'good', icon: '#i-hoe' });
491:     }
492:   }
493: 
494:   plantSeed(plot, type) {
495:     if (plot.crop) return;
496:     const def = CROPS[type];
497:     if (this.coins < def.cost) {
498:       this.audio.error();
499:       this.emit('toast', { text: `You need ${def.cost - this.coins} more coins for ${def.name} seeds.`, tone: 'warn', icon: '#i-coin' });
500:       return;
501:     }
502:     this.coins -= def.cost;
503:     if (!plot.tilled) plot.tilled = true;
504:     plot.crop = { type, growth: 0 };
505:     this.stats.planted++;
506:     this.audio.plant();
507:     this.burst(plot.x, plot.y, 8, ['#7da961', '#a9c87d', '#5e7f4a'], 0.9, 26, 0.45);
508:     this.floaters.push({ text: `-${def.cost}`, x: plot.x, y: plot.y - 22, vy: -22, life: 1, maxLife: 1, color: '#f2c96a', size: 12 });
509:     if (!this.tutorial.plant) {
510:       this.tutorial.plant = true;
511:       this.emit('toast', { text: 'Planted. Water it before dusk or it will not grow.', tone: 'good', icon: def.icon });
512:     }
513:     this.emit('tool-done', 'plant');
514:   }
515: 
516:   waterPlot(plot) {
517:     if (!plot.tilled) {
518:       this.emit('toast', { text: 'Till the soil before watering.', tone: '', icon: '#i-water', short: true });
519:       this.audio.error();
520:       return;
521:     }
522:     if (plot.watered) {
523:       this.emit('toast', { text: 'This plot is already watered.', tone: '', icon: '#i-water', short: true });
524:       return;
525:     }
526:     if (this.water <= 0) {
527:       this.audio.error();
528:       this.emit('toast', { text: 'The watering can is empty. Refill at the well.', tone: 'warn', icon: '#i-water' });
529:       return;
530:     }
531:     this.water--;
532:     plot.watered = true;
533:     this.audio.water();
534:     this.burst(plot.x, plot.y + 6, 10, ['#8fe0f0', '#c8f4ff', '#5fb8d8'], 0.9, 24, 0.5);
535:     this.emit('tool-done', 'water');
536:     if (!this.tutorial.water) {
537:       this.tutorial.water = true;
538:       this.emit('toast', { text: 'Watered. Crops grow at dawn. Rest at the farmhouse door when ready.', tone: 'good', icon: '#i-water' });
539:     }
540:   }
541: 
542:   harvest(plot) {
543:     const crop = plot.crop;
544:     if (!crop) return;
545:     const def = CROPS[crop.type];
546:     if (crop.growth < def.days) return;
547:     this.coins += def.sell;
548:     this.stats.coinsEarned += def.sell;
549:     this.stats.harvested++;
550:     plot.crop = null;
551:     plot.watered = false;
552:     plot.tilled = true;
553:     this.audio.harvest();
554:     this.audio.coin();
555:     this.floaters.push({
556:       text: `+${def.sell}`, x: plot.x, y: plot.y - 24, vy: -30, life: 1.35,
557:       maxLife: 1.35, color: '#ffe29b', size: 15,
558:     });
559:     this.burst(plot.x, plot.y - 6, 18, [def.color, '#f2c96a', '#ffffff', '#86ad6c'], 1.4, 60, 0.75);
560:     if (!this.tutorial.harvest) {
561:       this.tutorial.harvest = true;
562:       this.emit('toast', { text: `${def.name} harvested. Moon coins keep the lanterns lit.`, tone: 'good', icon: '#i-coin' });
563:     }
564:     this.emit('tool-done', 'harvest');
565:   }
