595:     this.shake = Math.max(this.shake, 4);
596:     this.burst(pad.x, pad.y, 26, [type.color, '#f2c96a', '#ffffff', '#6b5a3c'], 1.5, 70, 0.9);
597:     this.rings.push({ x: pad.x, y: pad.y, r: 10, maxR: 66, life: 0.55, maxLife: 0.55, color: type.color, width: 3 });
598:     if (!this.tutorial.build) {
599:       this.tutorial.build = true;
600:       this.emit('toast', { text: 'A ward is raised. It will fire on its own — keep the path covered.', tone: 'good', icon: type.icon });
601:     }
602:     this.emit('build-done', { pad, type });
603:     this.closeBuild();
604:     return true;
