610:       id: `tower-${pad.id}-${this.time}`,
611:       typeId,
612:       pad,
613:       x: pad.x,
614:       y: pad.y,
615:       level: 1,
616:       cooldown: Math.random() * 0.5,
617:       angle: -Math.PI / 2,
618:       recoil: 0,
619:       spin: Math.random() * TAU,
620:       invested: type.levels[0].cost,
621:       firing: 0,
622:       builtAt: this.time,
623:     };
