640:     if (this.coins < next.cost) {
641:       this.audio.error();
642:       this.emit('toast', { text: `Upgrading needs ${next.cost - this.coins} more coins.`, tone: 'warn', icon: '#i-coin' });
643:       return;
644:     }
645:     this.coins -= next.cost;
646:     tower.invested += next.cost;
647:     tower.level++;
648:     this.audio.upgrade();
649:     this.burst(tower.x, tower.y - 16, 20, [type.color, '#fff3c4', '#f2c96a'], 1.3, 55, 0.8);
650:     this.rings.push({ x: tower.x, y: tower.y, r: 6, maxR: 52, life: 0.6, maxLife: 0.6, color: type.color, width: 3 });
