712:       maxHp: hp,
713:       baseSpeed: base.speed * (1 + (this.day - 1) * 0.018),
714:       speed: base.speed,
715:       damage: base.damage,
716:       radius: base.radius,
717:       color: base.color,
718:       d: -Math.random() * 12,
719:       x: -40,
720:       y: 150,
721:       angle: 0,
722:       dead: false,
723:       slowTimer: 0,
724:       slowFactor: 1,
725:       hitFlash: 0,
726:       bob: Math.random() * TAU,
