737:   updateTowers(dt) {
738:     for (const tower of this.towers) {
739:       const stats = this.getTowerStats(tower);
740:       tower.cooldown -= dt;
741:       tower.recoil = Math.max(0, tower.recoil - dt * 5);
742:       tower.spin += dt * (tower.typeId === 'frost' ? 1.9 : 0.7);
743:       if (tower.firing > 0) tower.firing -= dt;
744:       if (tower.cooldown > 0) continue;
745:       if (tower.typeId === 'frost') {
746:         const hit = this.enemies.filter((e) => !e.dead && dist(tower.x, tower.y, e.x, e.y) <= stats.range + e.radius);
747:         if (hit.length) {
748:           tower.cooldown = stats.cd;
749:           tower.firing = 0.3;
750:           this.rings.push({
751:             x: tower.x, y: tower.y, r: 8, maxR: stats.range,
752:             life: 0.5, maxLife: 0.5, color: '#a8dcff', width: 2,
753:           });
754:           for (const e of hit) {
755:             this.damageEnemy(e, stats.dmg);
756:             this.applySlow(e, stats.slow, stats.slowTime);
757:           }
758:           if (this.shotSfxTimer <= 0) {
759:             this.audio.frost();
760:             this.shotSfxTimer = 0.22;
761:           }
762:         }
763:         continue;
764:       }
765:       let target = null;
766:       let best = -Infinity;
767:       for (const e of this.enemies) {
768:         if (e.dead) continue;
769:         const d = dist(tower.x, tower.y, e.x, e.y);
770:         if (d <= stats.range + e.radius && e.d > best) {
771:           best = e.d;
772:           target = e;
773:         }
774:       }
775:       if (target) {
776:         tower.cooldown = stats.cd;
777:         tower.recoil = 1;
778:         tower.firing = 0.2;
779:         tower.angle = Math.atan2(target.y - tower.y, target.x - tower.x);
780:         if (tower.typeId === 'lantern') {
781:           this.projectiles.push({
782:             kind: 'bolt', x: tower.x + Math.cos(tower.angle) * 16, y: tower.y - 30,
783:             target, speed: 430, dmg: stats.dmg, color: '#ffd479', life: 2.4, trail: [],
784:           });
785:           if (this.shotSfxTimer <= 0) {
786:             this.audio.shoot();
787:             this.shotSfxTimer = 0.12;
788:           }
789:         } else {
790:           this.projectiles.push({
791:             kind: 'seed', sx: tower.x, sy: tower.y - 34, x: tower.x, y: tower.y - 34,
792:             tx: target.x, ty: target.y, t: 0, dur: 0.55,
793:             dmg: stats.dmg, splash: stats.splash, color: '#a6d27e', target,
794:           });
795:           if (this.shotSfxTimer <= 0) {
796:             this.audio.bramble();
797:             this.shotSfxTimer = 0.18;
798:           }
799:         }
800:       }
801:     }
