804:   updateEnemies(dt) {
805:     for (const e of this.enemies) {
806:       if (e.dead) continue;
807:       e.spawn = Math.min(1, e.spawn + dt * 3);
808:       e.bob += dt * 2.2;
809:       e.hitFlash = Math.max(0, e.hitFlash - dt * 4);
810:       if (e.slowTimer > 0) {
811:         e.slowTimer -= dt;
812:         e.slowFactor = e.slowAmount || 0.6;
813:       } else {
814:         e.slowFactor = 1;
815:       }
816:       const speed = e.baseSpeed * e.slowFactor;
817:       e.d += speed * dt;
818:       const pos = pointAtDistance(this.path, e.d);
819:       e.x = pos.x;
820:       e.y = pos.y;
821:       e.angle = pos.angle;
822:       if (e.d >= this.path.length - 3) {
823:         this.enemyReachedHouse(e);
824:       }
825:     }
826:     this.enemies = this.enemies.filter((e) => !e.dead);
