829:   applySlow(enemy, amount, time) {
830:     if (!enemy || enemy.dead) return;
831:     enemy.slowAmount = 1 - amount;
832:     enemy.slowFactor = Math.min(enemy.slowFactor, 1 - amount);
833:     enemy.slowTimer = Math.max(enemy.slowTimer, time);
