844:       this.audio.enemyDie();
845:       const colors = enemy.type === 'wisp'
846:         ? ['#9be9f5', '#e6ffff', '#5fb8d8']
847:         : enemy.type === 'brute'
848:           ? ['#5a3f66', '#8c6ba6', '#2c2038']
849:           : ['#4b3a78', '#9c86d4', '#221a38'];
850:       this.burst(enemy.x, enemy.y, enemy.type === 'boss' ? 50 : 16, colors, 1.2, enemy.type === 'boss' ? 110 : 55, 0.9);
851:       const reward = enemy.type === 'boss' ? 60 : 2;
852:       this.coins += reward;
853:       this.stats.coinsEarned += reward;
854:       if (reward > 2) {
855:         this.floaters.push({ text: `+${reward}`, x: enemy.x, y: enemy.y - 18, vy: -22, life: 1, maxLife: 1, color: '#ffe29b', size: 13 });
856:       }
