882:   updateProjectiles(dt) {
883:     for (const p of this.projectiles) {
884:       if (p.dead) continue;
885:       if (p.kind === 'bolt') {
886:         const target = p.target;
887:         if (!target || target.dead) {
888:           p.life -= dt;
889:           p.x += Math.cos(p.angle || 0) * p.speed * dt * 0.4;
890:           p.y += Math.sin(p.angle || 0) * p.speed * dt * 0.4;
891:           if (p.life <= 0) p.dead = true;
892:           continue;
893:         }
894:         const dx = target.x - p.x;
895:         const dy = target.y - 8 - p.y;
896:         const d = Math.hypot(dx, dy);
897:         p.angle = Math.atan2(dy, dx);
898:         if (d < 13) {
899:           p.dead = true;
900:           this.damageEnemy(target, p.dmg);
901:           this.burst(target.x, target.y - 8, 7, ['#ffe29b', '#f2c96a', '#fff8dc'], 0.7, 32, 0.45);
902:           continue;
903:         }
904:         p.trail.push({ x: p.x, y: p.y, life: 0.25 });
905:         if (p.trail.length > 9) p.trail.shift();
906:         p.x += (dx / d) * p.speed * dt;
907:         p.y += (dy / d) * p.speed * dt;
908:         p.life -= dt;
909:         if (p.life <= 0) p.dead = true;
910:       } else if (p.kind === 'seed') {
911:         p.t += dt / p.dur;
912:         if (p.t >= 1) {
913:           p.dead = true;
914:           this.damageArea(p.tx, p.ty, p.splash, p.dmg);
915:           this.rings.push({ x: p.tx, y: p.ty, r: 4, maxR: p.splash, life: 0.42, maxLife: 0.42, color: '#a6d27e', width: 4 });
916:           this.burst(p.tx, p.ty, 16, ['#a6d27e', '#7da961', '#4c6e3c', '#d9e8a8'], 0.9, 64, 0.8);
917:           this.audio.hit();
918:           continue;
919:         }
920:         const targetX = p.target && !p.target.dead ? p.target.x : p.tx;
921:         const targetY = p.target && !p.target.dead ? p.target.y : p.ty;
922:         p.tx = lerp(p.tx, targetX, 0.14);
923:         p.ty = lerp(p.ty, targetY, 0.14);
924:         p.x = lerp(p.sx, p.tx, p.t);
925:         p.y = lerp(p.sy, p.ty, p.t) - Math.sin(p.t * Math.PI) * 60;
926:       }
927:     }
928:     this.projectiles = this.projectiles.filter((p) => !p.dead);
929:   }
