1052:   findNearby() {
1053:     const p = this.player;
1054:     let best = null;
1055:     const consider = (kind, target, radius, prompt) => {
1056:       const d = dist(p.x, p.y, target.x, target.y);
1057:       if (d <= radius && (!best || d < best.dist)) {
1058:         best = { kind, target, dist: d, prompt };
1059:       }
1060:     };
1061:     for (const plot of this.plots) {
1062:       if (dist(p.x, p.y, plot.x, plot.y) > 78) continue;
1063:       consider('plot', plot, 78, this.plotPrompt(plot));
1064:     }
1065:     for (const pad of this.pads) {
1066:       if (pad.tower) consider('tower', pad, 66, `Inspect the ${TOWER_TYPES[pad.tower.typeId].name}`);
1067:       else consider('pad', pad, 62, 'Build a ward on this stone pad');
1068:     }
1069:     consider('well', WELL, 98, this.water >= WATER_CAPACITY ? 'The can is full' : 'Refill the watering can');
1070:     if (this.phase === 'day' || this.phase === 'dawn') {
1071:       consider('door', { x: HOUSE.doorX, y: HOUSE.doorY + 18 }, 92, 'Rest until nightfall');
1072:     }
1073:     return best;
1074:   }
