1076:   plotPrompt(plot) {
1077:     const tool = TOOLS[this.selectedTool];
1078:     if (plot.crop) {
1079:       const def = CROPS[plot.crop.type];
1080:       if (plot.crop.growth >= def.days) return `Harvest the ${def.name}`;
1081:       if (!plot.watered) return `Water the ${def.name}`;
1082:       return `${def.name} is watered`;
1083:     }
1084:     if (!plot.tilled) {
1085:       if (tool.kind === 'seed') return `Plant ${CROPS[tool.id].name} (tills first)`;
1086:       return 'Till the soil';
1087:     }
1088:     if (tool.kind === 'seed') return `Plant ${CROPS[tool.id].name}`;
1089:     if (tool.id === 'water') return 'Water the soil';
1090:     return 'Choose a seed to plant';
1091:   }
